/** 
 * Find or create contact by ID. In IRC every chat room member is also a contact. Try to find a contact by its ID. If a contact cannot be found, then create one.
 * @param id id of the contact
 * @return returns instance of contact
 */
Contact findOrCreateContactByID(final String id){
  Contact contact=findContactByID(id);
  if (contact == null) {
    try {
      contact=createVolatileContact(id);
      LOGGER.debug("No existing contact found. Created volatile contact" + " for nick name '" + id + "'.");
    } catch (RuntimeException e) {
      LOGGER.error("Failed to create volatile contact for '" + id + "'", e);
      throw e;
    }
  }
  return contact;
}
